    /// <summary>Read-only metadata for all glyphs, in stable enum order.</summary>
    public static IReadOnlyList<OneIconInfo> All { get; } = Array.AsReadOnly(Entries.Select(entry => entry.Info).ToArray());

    /// <summary>Gets metadata for a valid enum value. Throws for undefined values.</summary>
    public static OneIconInfo Get(OneIconKind kind) => EntryFor(kind).Info;

    internal static Glyph Drawing(OneIconKind kind) => EntryFor(kind).Drawing.Value;

    private static Entry EntryFor(OneIconKind kind) => (uint)kind < (uint)Entries.Length
        ? Entries[(int)kind] : throw new ArgumentOutOfRangeException(nameof(kind));

    internal sealed class Glyph(Geometry outline, string? filled)
    {
        private readonly Lazy<Geometry>? _filled = filled is null ? null : new(() => Geometry.Parse(filled));
        public Geometry Outline { get; } = outline;
        public Geometry? Filled => _filled?.Value;
    }

    private sealed class Entry(OneIconKind kind, OneIconCategory category, string displayName, string outline, string? filled = null)
    {
        public OneIconInfo Info { get; } = new(kind, category, kind.ToString(), displayName, filled is not null);
        // Parse only when a glyph is used. Callers never receive mutable shared Geometry instances.
        public Lazy<Glyph> Drawing { get; } = new(() => new(Geometry.Parse(outline), filled));
    }
}
